  const OKUL1 = "<i>Dağ köyünde yaşayan Aras, her sabah güneş doğmadan yola çıkar. Okuluna varmak için bir saat yürür, küçük bir dereyi taşların üstünden atlayarak geçer. Kışın yollar karla kapanınca babası onu katırla okula götürür. Aras yorulsa da hiç şikâyet etmez; çünkü büyüyünce köyüne öğretmen olarak dönmek istiyor.</i>";
  const OKUL2 = "<i>Geniş bir nehrin kıyısındaki köyde okul, nehrin öbür yakasındadır. Çocuklar her sabah küçük bir kayığa binerek karşıya geçer. Yağmurlu günlerde nehir coşar, kayık sallanır. Yine de çocuklar can yeleklerini giyip kitaplarını naylon torbalara sararak yola koyulur.</i>";
  const OKUL3 = "<i>Çölün ortasındaki bir kasabada okul, sıcak yüzünden sabahın çok erken saatinde başlar. Öğle sıcağı bastırmadan dersler biter. Okulda yeterince sıra olmadığı için bazı öğrenciler hasırların üstünde oturur. Öğretmenleri “Bilgi, sıraya değil merak eden yüreğe sığar.” der.</i>";

